using System.Collections.Generic;

public static class Dedup
{
    public static List<int> RemoveDuplicates(List<int> input)
    {
        var result = new List<int>();
        foreach (var item in input)
        {
            bool found = false;
            foreach (var existing in result)
            {
                if (existing == item)
                {
                    found = true;
                    break;
                }
            }
            if (!found)
            {
                result.Add(item);
            }
        }
        return result;
    }
}

