using System;
using System.Collections.Generic;
using System.Diagnostics;
using Xunit;

public class PerfTests
{
    [Fact]
    public void RemovesDuplicatesQuickly()
    {
        var input = new List<int>();
        var rnd = new Random(42);
        for (int i = 0; i < 200000; i++)
        {
            input.Add(rnd.Next(0, 2000000));
        }

        var expected = new List<int>();
        var seen = new HashSet<int>();
        foreach (var x in input)
        {
            if (seen.Add(x)) expected.Add(x);
        }

        var sw = Stopwatch.StartNew();
        var result = Dedup.RemoveDuplicates(input);
        sw.Stop();

        Assert.Equal(expected, result);
        Assert.True(sw.ElapsedMilliseconds < 4000, $"Too slow: {sw.ElapsedMilliseconds}ms (expected an O(n) HashSet-based implementation)");
    }
}
